def check_solution(a_p):
    def a(p):
        return a_p[p]

    for p in range(10):
        LHS = a(a(a(p)))
        RHS = a(p+1) + 1
        if LHS != RHS:
            return False, p
    return True, None

# Test a_p = p + 1
a_p_linear = {i: i + 1 for i in range(10)}
is_valid, failed_p = check_solution(a_p_linear)

print(f"Test a_p = p + 1: Valid={is_valid}, Failed at p={failed_p}")

# Test a_p = p + 2
a_p_shifted = {i: i + 2 for i in range(10)}
is_valid_shifted, failed_p_shifted = check_solution(a_p_shifted)

print(f"Test a_p = p + 2: Valid={is_valid_shifted}, Failed at p={failed_p_shifted}")
